package tech.lunos.ide.core

import com.google.gson.JsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

// The shared fixtures (sdks/ide/fixtures/hunks), generated by packages/opencode/test/ide/hunk-fixtures.ts
// from the same `diff` calls the server makes. The C# tests read the same files.
class HunksTest {
    private val fixtures = File(System.getProperty("lunos.fixtures") ?: "../ide/fixtures/hunks")
        .listFiles { file -> file.name.endsWith(".json") }!!
        .sortedBy { it.name }
        .map { JsonParser.parseString(it.readText()).asJsonObject }

    @Test
    fun `fixtures are there`() {
        assertTrue(fixtures.size >= 6)
    }

    @Test
    fun `every accept-reject combination gives exactly the expected file`() {
        for (fixture in fixtures) {
            val name = fixture["name"].asString
            val patch = FilePatch.parse(fixture["patch"].asString)
            val after = fixture["after"].asString
            assertEquals(name, fixture["hunks"].asInt, patch.hunks.size)
            for (case in fixture["cases"].asJsonArray.map { it.asJsonObject }) {
                val accept = case["accept"].asJsonArray.map { it.asBoolean }
                assertEquals("$name $accept", case["expected"].asString, patch.apply(after, accept))
            }
            assertEquals(name, fixture["before"].asString, patch.before(after))
        }
    }

    @Test
    fun `hunks say where they are and what they change`() {
        val fixture = fixtures.first { it["name"].asString == "two-hunks" }
        val hunks = FilePatch.parse(fixture["patch"].asString).hunks
        assertEquals(listOf(4, 8), hunks.map { it.line })
        assertEquals(listOf("  int Add(int a, int b) { return a + b; }\n"), hunks[0].removed)
        assertEquals(listOf("  int Mul(int a, int b) => a * b;\n"), hunks[1].added)
    }

    @Test
    fun `a file changed after the edit is refused, not fuzzed`() {
        val fixture = fixtures.first { it["name"].asString == "two-hunks" }
        val patch = FilePatch.parse(fixture["patch"].asString)
        val edited = fixture["after"].asString.replace("class Calc", "class Calculator")
        assertThrows(StalePatchException::class.java) { patch.apply(edited, listOf(true, false)) }
    }

    @Test
    fun `a patch with ordinary context and two sections`() {
        val before = (1..20).joinToString("") { "line $it\n" }
        val after = before.replace("line 2\n", "line two\n").replace("line 18\n", "line eighteen\n")
        val patch = """
            Index: f.txt
            ===================================================================
            --- f.txt
            +++ f.txt
            @@ -1,5 +1,5 @@
             line 1
            -line 2
            +line two
             line 3
             line 4
             line 5
            @@ -15,6 +15,6 @@
             line 15
             line 16
             line 17
            -line 18
            +line eighteen
             line 19
             line 20
        """.trimIndent() + "\n"
        val parsed = FilePatch.parse(patch)
        assertEquals(2, parsed.hunks.size)
        assertEquals(before.replace("line 2\n", "line two\n"), parsed.apply(after, listOf(true, false)))
        assertEquals(before, parsed.before(after))
    }

    @Test
    fun `a file saved with a BOM applies against the server's patch, which has none`() {
        val fixture = fixtures.first { it["name"].asString == "two-hunks" }
        val patch = FilePatch.parse(fixture["patch"].asString)
        val onDisk = "\uFEFF" + fixture["after"].asString
        assertThrows(StalePatchException::class.java) { patch.apply(onDisk, listOf(true, false)) }
        assertEquals(fixture["cases"].asJsonArray[1].asJsonObject["expected"].asString, patch.apply(FilePatch.withoutBom(onDisk), listOf(true, false)))
    }
}
